    if node.cpu_capacity == 0:
        return node.power_idle_w + node.power_max_w
    cpu_ratio = float(pod.cpu_request) / float(node.cpu_capacity)
    return node.power_idle_w + node.power_max_w * cpu_ratio

def propose_moves(state: ClusterState, graph: CallGraphCtx, budget: int) -> list[Move]:
    out: list[Move] = []
    if budget <= 0:
        return out
    moved = 0
    for i in range(len(state.pods)):
        pod = state.pods[i]
        if pod.current_node >= 0:
            if not pod.stateful and not pod.has_pdb:
                current_node = state.nodes[pod.current_node]
                current_lat = latency_penalty_graph(pod, current_node, state.pods, graph)
                current_energy = node_energy_for_pod(current_node, pod) + 0.1 * current_lat
                save = 0.0
                if current_node.suspendable and current_node.cpu_allocated == pod.cpu_request and current_node.mem_allocated == pod.mem_request:
                    save = current_node.power_idle_w
                best_target = -1
                best_delta = 0.0
                for t in range(len(state.nodes)):
                    target = state.nodes[t]
                    if t != pod.current_node and target.cpu_allocated + pod.cpu_request <= target.cpu_capacity and target.mem_allocated + pod.mem_request <= target.mem_capacity:
                        new_lat = latency_penalty_graph(pod, target, state.pods, graph)
                        new_energy = node_energy_for_pod(target, pod) + 0.1 * new_lat
                        delta = new_energy - (current_energy - save)
                        if delta < best_delta:
                            best_delta = delta
                            best_target = t
                if best_target >= 0:
                    out.append(move_pod(pod.id, best_target))
                    moved += 1
                    if moved >= budget:
                        return out
    return out
